//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::copy_slice`; the
//! native twin is `benches/native/Bench/ArrayCopySlice.lean`.
//! the array is updated in place on both sides (Lean's is unique after its first copy of the
//! input, the Rust twin's a copy made once); offsets anywhere in the 64-byte source and
//! destination, lengths up to 15, so the destination grows to at most 78 bytes

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u8>, n: u64) -> u64 {
    let src = &inp[..];
    let mut st = inp.clone();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        if let Some(p) = array::copy_slice(
            src.len(),
            nat_unbox(nat_box(x >> 58)),
            st.len(),
            nat_unbox(nat_box((x >> 52) & 63)),
            nat_unbox(nat_box((x >> 46) & 15)),
        ) {
            if st.len() < p.new_len {
                st.resize(p.new_len, 0);
            }
            st[p.dest_start..p.dest_start + p.len]
                .copy_from_slice(&src[p.src_start..p.src_start + p.len]);
        }
        acc = mix(
            acc,
            st.len() as u64 + u64::from(st[((x >> 40) & 63) as usize]),
        );
    }
    acc
}

fn main() {
    run(|| src_bytes(), kernel)
}
